from openpyxl import load_workbook

wb = load_workbook('/root/gdp.xlsx', data_only=True)
data = wb['Data']

print(f"Data sheet: max_row={data.max_row}, max_col={data.max_column}")

print("\n--- Data sheet rows 1-5 (headers) ---")
for row in data.iter_rows(min_row=1, max_row=5, min_col=1, max_col=15, values_only=False):
    row_data = []
    for cell in row:
        val = cell.value
        if val is not None:
            row_data.append(f"[{cell.coordinate}]={repr(val)}")
    if row_data:
        print(", ".join(row_data))

